refentry.refsect1:
&reftitle.parameters;


  key


    The key of the element to retrieve.

&reftitle.returnvalues;

 Returns the cached element, or &null; if there is no element with the
 given key in the cache.

&reftitle.errors;
Throws a BadMethodCallException if the CachingIterator::FULL_CACHE flag is not set.
Emits an E_WARNING if there is no element with the given key in the cache.

  &reftitle.examples;

   Accessing elements that have been iterated over


<?php
$iterator = new CachingIterator(
    new ArrayIterator(['apple' => 3, 'banana' => 5, 'cherry' => 7]),
    CachingIterator::FULL_CACHE
);

foreach ($iterator as $fruit => $count) {
    if ($fruit === 'banana') {
        break;
    }
}

var_dump($iterator['apple']);
var_dump(isset($iterator['cherry']));
?>


   &example.outputs;


int(3)
bool(false)
